def page(path,title,desc,content,home=False,post=None):
 url=base+path
 schema={'@context':'https://schema.org','@type':'WebSite' if home else 'WebPage','name':title,'url':url,'description':desc}
 if home:schema={'@context':'https://schema.org','@graph':[schema,{'@type':'Book','name':'Sleep Reset System','bookFormat':'https://schema.org/EBook','inLanguage':'en','description':'A practical 21-day educational guide to sleep habits, evening routines and sleep tracking.','url':url}]}
 if post:
  schema={'@context':'https://schema.org','@type':'BlogPosting','headline':post['title'],'description':desc,'datePublished':post['date'],'dateModified':post.get('updated') or post['date'],'author':{'@type':'Organization','name':'Sleep Reset System','url':base+'/about/'},'mainEntityOfPage':url}
  if post.get('image'): schema['image']=base+post['image']
 title=escape(title,quote=True);desc=escape(desc,quote=True)
 schema_json=json.dumps(schema).replace('<','\\u003c')
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{desc}"><link rel="canonical" href="{url}"><meta name="robots" content="index,follow"><meta property="og:type" content="website"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{url}"><meta property="og:image" content="{base}/assets/guide-cover.png"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#203f37"><link rel="stylesheet" href="/style.css"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><script type="application/ld+json">{schema_json}</script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/">◔ SLEEP RESET SYSTEM</a><nav><a class="hide" href="/#inside">The guide</a><a href="/blog/">Blog</a><a href="/#faq">FAQs</a></nav></header><main id="main">{content}</main><footer><span>© 2026 Sleep Reset System · General sleep education</span><div><a href="/about/">About & contact</a> · <a href="/privacy/">Privacy</a> · <a href="/terms/">Terms & purchases</a></div></footer></body></html>'''
 html=html.replace('https://payhip.com/b/xZzcv',escape(checkout,quote=True))
 dest=p/'index.html' if path=='/' else p/path.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(html)
home='''<section class="hero"><div><div class="eyebrow">A little structure for your evenings</div><h1>Build a calmer<br>bedtime routine.</h1><p class="intro">Build a more consistent sleep routine, one small habit at a time. A practical 21-day guide to understanding your evenings and noticing what works for you.</p><a class="button" href="https://payhip.com/b/xZzcv">Explore the guide on Payhip ↗</a><a class="secondary" href="#inside">Take a look inside ↓</a><p class="fine">Digital PDF guide · 21-day sleep diary included<br>View current price and purchase details on Payhip.</p></div><div class="book-stage"><img src="/assets/guide-cover.png" width="773" height="1000" alt="Cover of Sleep Reset System: A Practical 21-Day Guide to Building More Consistent Sleep Habits" fetchpriority="high"><div class="caption">YOUR EVENING. A FRESH START.</div></div></section><div class="strip"><span>01 / Understand your habits</span><span>02 / Build a routine</span><span>03 / Notice your patterns</span></div><section class="section split" id="inside"><div><div class="eyebrow">What's inside</div><h2>Less guesswork.<br>More intention.</h2><p>This guide brings everyday sleep education into one organised place. Read at your own pace, explore the checklists, and use the diary to reflect on your routine.</p><p class="fine">For adults seeking general sleep-habit education. It is not a clinical treatment programme.</p></div><ul class="list"><li><span>01</span><strong>Understand the basics</strong><br>Explore sleep pressure, circadian rhythm and common sleep patterns.</li><li><span>02</span><strong>Shape your evenings</strong><br>Sleep hygiene checklists, wind-down ideas and relaxation techniques.</li><li><span>03</span><strong>Build consistency</strong><br>A structured 21-day framework for exploring your sleep-wake habits.</li><li><span>04</span><strong>Keep a record</strong><br>A 21-day sleep diary and quick reference guide to revisit along the way.</li></ul></section><section class="section"><div class="eyebrow">A framework, at your pace</div><h2>A small step is still a start.</h2><div class="weeks"><article><div class="eyebrow">Understand</div><h3>Start with curiosity.</h3><p>Learn the concepts before choosing which everyday habits to explore. You don't need to change everything at once.</p></article><article><div class="eyebrow">Explore</div><h3>Give your evening structure.</h3><p>Use the guide's routine ideas and checklists to reflect on a wind-down routine that fits your life.</p></article><article><div class="eyebrow">Reflect</div><h3>Look for your patterns.</h3><p>Record observations in the sleep diary. The 21 days provide structure, not a deadline for achieving a result.</p></article></div></section><section class="section split"><div><div class="eyebrow">Start here, for free</div><h2>Get to know your routine.</h2></div><div class="quote"><h3>What does your evening look like?</h3><p>Think about when you stop working, how you unwind and what time you wake up. Observing your routine is a useful starting point for a conversation about your sleep.</p><a href="/sleep-habit-guide/">Read our introduction to sleep habits →</a></div></section><section class="section faq" id="faq"><div class="eyebrow">Before you begin</div><h2>A few good questions.</h2>'''
faqs=[('What am I buying?','A digital educational PDF covering sleep habits, evening routines, sleep tracking and a 21-day framework. It includes a sleep diary and quick reference guide. It is not a physical book or an individual coaching service.'),('Will it cure insomnia or fix my sleep in 21 days?','No outcome is promised. The 21 days describe the framework, not a guaranteed recovery period. This guide does not diagnose, treat, cure or prevent insomnia or other conditions.'),('Is this CBT-I treatment?','No. The guide discusses selected CBT-I-informed concepts for general education. It is not personalised CBT-I, therapy or medical advice, and the creator is not a doctor, sleep specialist or licensed therapist.'),('Where do I see the price and purchase the guide?','Use the Payhip link to view the current price, currency, checkout details and seller information. Payment and digital delivery are handled through Payhip. Review the seller’s purchase and refund information there before paying.'),('When should I get professional advice?','Speak with a qualified healthcare professional if sleep difficulties persist, are severe or affect daily life. Seek advice before changing your schedule if you have a medical or psychiatric condition, are pregnant, or drive or work in a safety-critical role.')]
